BEGIN_PGML Suppose you have three dice: a 4-sided die, a 6-sided die, and an 8-sided die. Each die is fair and numbered from 1 to the number of sides it has. You roll all three dice.
END_PGML
############################################################ # Scaffold ############################################################ Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => when_previous_correct,);
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML What is the probability that the sum of the dice is 3?
[_]{'1/(4*6*8)'}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML What is the probability that the sum of the dice is 6?
[_]{'10/(4*6*8)'}{5}
END_PGML
############################################################ # Hint ############################################################ #Set value of $showHint in PGcourse.pl for course-wide attempt threshhold for revealing hints
BEGIN_PGML_HINT You could list out all the ways you can get a 6, or use sticks and stones.
END_PGML_HINT
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML What is the probability all three dice have the same number when rolled?
[_]{'4/(4*6*8)'}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML What is the probability all three dice have the same number when rolled _given_ that the sum of the dice is 6?
[_]{'1/10'}{5}
END_PGML
Section::End();
